payload.text:
This site runs **no practice simulator** for rollouts (no `stages`/`sim_reward`/`final_state`), consistent with the playbook. So my only window into the sub-goal state is a `train.py` call's `reward_fn(state)` → `score_mean`, and importantly each train step also records `task_completed` (the **full** task success on those same rollouts).

Key plan: run cheap 1-step **probe** trains (fresh LoRA, full goal kept, custom binary reward = a core sub-goal). Each probe (0.21 GPU-h) tells me (a) `score_mean` = base's sub-goal reach rate and (b) `task_completed` = base's full-task rate on 64 practice rollouts. GRPO only updates on reward variance, so I need sub-goals the base reaches *sometimes*. Let me write robust, defensive reward files (only `numpy`/`math`, `try/except` so no crashes) and submit 6 probes across the most tractable task types.

```bash
cd …/rc_dec1r_s2/workspace
mkdir -p rewards
python3 - <<'PY'
import os
hdr = """import numpy as np
def _v(x):
    try:
        a = np.asarray(x, dtype=float).ravel()
        if a.size == 3:
            return a
    except Exception:
        pass
    return None
def _box_of(reg):
    pts = []
    def walk(o):
        if isinstance(o, dict):
            for k, val in o.items():
                if k in ("p0", "px", "py", "pz"):
                    v = _v(val)
                    if v is not None:
                        pts.append(v)
                else:
                    walk(val)
        elif isinstance(o, (list, tuple)):
            for e in o:
                walk(e)
    walk(reg)
    if len(pts) >= 2:
        return (np.minimum.reduce(pts), np.maximum.reduce(pts))
    return None
def _inside(pos, reg):
    b = _box_of(reg)
    if b is None:
        return False
    lo, hi = b
    p = _v(pos)
    if p is None:
        return False
    return bool(np.all(p >= lo - 0.02) and np.all(p <= hi + 0.02))
def _fx(state, *subs):
    out = []
    fx = state.get("fixtures") or {}
    for name, f in fx.items():
        if any(s in str(name).lower() for s in subs):
            out.append((name, f or {}))
    return out
def _touch(contacts, *subs):
    for c in (contacts or []):
        cs = str(c).lower()
        if any(s in cs for s in subs):
            return True
    return False
def _hdist(a, b):
    pa, pb = _v(a), _v(b)
    if pa is None or pb is None:
        return 9.9
    d = pa - pb
    return float(np.sqrt(d[0]*d[0] + d[1]*d[1]))
def _obj_by(state, *subs, excl=()):
    out = []
    objs = state.get("objects") or {}
    for name, o in objs.items():
        n = str(name).lower()
        if any(s in n for s in subs) and not any(e in n for e in excl):
            out.append((name, o or {}))
    return out
"""
def W(fn, body):
    open(fn, "w").write(hdr + body)

W("rewards/p_boil.py", """
def reward_fn(state):
    try:
        for name, o in _obj_by(state, "pot", "pan", excl=("pancake",)):
            if _touch(o.get("contacts"), "stove"):
                return 1
            for fname, f in _fx(state, "stove"):
                if _inside(o.get("pos"), f.get("regions")):
                    return 1
        return 0
    except Exception:
        return 0
""")

W("rewards/p_mw.py", """
def reward_fn(state):
    try:
        foods = _obj_by(state, "chicken", "drumstick", "meat", "food")
        for name, o in foods:
            if _touch(o.get("contacts"), "microwave"):
                return 1
            for fname, f in _fx(state, "microwave"):
                if _inside(o.get("pos"), f.get("regions")):
                    return 1
        return 0
    except Exception:
        return 0
""")

W("rewards/p_tong.py", """
def reward_fn(state):
    try:
        for name, o in _obj_by(state, "tong"):
            if _touch(o.get("contacts"), "counter"):
                return 1
            for fname, f in _fx(state, "counter"):
                if _inside(o.get("pos"), f.get("regions")):
                    return 1
        return 0
    except Exception:
        return 0
""")

W("rewards/p_ice.py", """
def reward_fn(state):
    try:
        glasses = [o for _, o in _obj_by(state, "glass", "cup", "lemonade")]
        for name, o in _obj_by(state, "lemon", "ice"):
            for g in glasses:
                if _hdist(o.get("pos"), g.get("pos")) < 0.5:
                    return 1
            if _touch(o.get("contacts"), "glass", "cup"):
                return 1
        return 0
    except Exception:
        return 0
""")

W("rewards/p_utensil.py", """
def reward_fn(state):
    try:
        for name, o in _obj_by(state, "utensil", "spoon", "fork", "knife", "spatula", "ladle", "tong"):
            if _touch(o.get("contacts"), "drawer"):
                return 1
            for fname, f in _fx(state, "drawer"):
                if _inside(o.get("pos"), f.get("regions")):
                    return 1
        return 0
    except Exception:
        return 0
""")

W("rewards/p_straw.py", """
def reward_fn(state):
    try:
        cakes = [o for _, o in _obj_by(state, "pancake")]
        for name, o in _obj_by(state, "strawberry", "fruit"):
            for c in cakes:
                if _hdist(o.get("pos"), c.get("pos")) < 0.7:
                    return 1
            if _touch(o.get("contacts"), "pancake", "plate"):
                return 1
        return 0
    except Exception:
        return 0
""")
print("wrote rewards:", sorted(os.listdir("rewards")))
PY
