hdr = """import numpy as np
SUBS = {SUBS}

def _v(x):
    try:
        a = np.asarray(x, dtype=float).ravel()
        return a if a.size == 3 else None
    except Exception:
        return None

def _box_of(reg):
    pts = []
    def walk(o):
        if isinstance(o, dict):
            for k, val in o.items():
                if k in ("p0","px","py","pz"):
                    v = _v(val)
                    if v is not None: pts.append(v)
                else: walk(val)
        elif isinstance(o, (list, tuple)):
            for e in o: walk(e)
    walk(reg)
    if len(pts) >= 2:
        return (np.minimum.reduce(pts), np.maximum.reduce(pts))
    return None

def _fx(state, *subs):
    out = []
    for name, f in (state.get("fixtures") or {}).items():
        if any(s in str(name).lower() for s in subs):
